def _max_lower(
    a: tuple[Version, bool] | None,
    b: tuple[Version, bool] | None,
) -> tuple[Version, bool] | None:
    """Return the stronger (higher) of two lower bounds."""
    if a is None:
        return b
    if b is None:
        return a
    av, ai = a
    bv, bi = b
    if bv != av:
        return b if bv > av else a
    # Same version: exclusive (False) is stronger
    return b if not bi else a


def _min_upper(
    a: tuple[Version, bool] | None,
    b: tuple[Version, bool] | None,
) -> tuple[Version, bool] | None:
    """Return the stronger (lower) of two upper bounds."""
    if a is None:
        return b
    if b is None:
        return a
    av, ai = a
    bv, bi = b
    if bv != av:
        return b if bv < av else a
    # Same version: exclusive (False) is stronger
    return b if not bi else a
